#!/usr/bin/env node
// Mirror the installable plugin payloads from zai-org/zcode-plugins into this repo.
// Plugin bytes are written straight out of the upstream commit objects; only
// `.zcode-plugin-seed.json` (a local install artifact) is dropped. Everything else
// in the repo is generated by compose.mjs.
//
// Why objects and not the checkout: upstream's .gitattributes is `* text=auto`
// plus `eol=lf` for a short extension list, so on Windows the checkout hands back
// CRLF for LICENSE / *.txt / *.bat no matter what core.autocrlf says. Copying that
// tree would publish bytes that are not upstream's, and this repo's whole promise
// is that a mirrored plugin is byte-identical to what `zai-org/zcode-plugins`
// stores. Cat-file cannot be rewritten by an EOL filter.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { ROOT, UPSTREAM_DIR, DATA_DIR, loadConfig, hasGit, git, readJson, writeJson } from './lib.mjs';

const cfg = loadConfig();

const NO_EOL_REWRITE = ['-c', 'core.autocrlf=false', '-c', 'core.eol=lf'];

if (!hasGit(UPSTREAM_DIR)) {
  console.log(`[sync] cloning ${cfg.upstream} (depth 1)`);
  execFileSync('git', [...NO_EOL_REWRITE, 'clone', '--depth', '1', '--branch', cfg.upstreamBranch, cfg.upstream, UPSTREAM_DIR], { stdio: 'inherit' });
} else {
  console.log('[sync] fetching upstream');
  git(UPSTREAM_DIR, 'config', 'core.autocrlf', 'false');
  git(UPSTREAM_DIR, 'config', 'core.eol', 'lf');
  git(UPSTREAM_DIR, 'remote', 'set-url', 'origin', cfg.upstream);
  git(UPSTREAM_DIR, 'fetch', '--depth', '1', 'origin', cfg.upstreamBranch);
  // -f forces the rewrite even when the commit is already checked out; the bytes
  // below come from objects, so this line is about tidiness, not correctness.
  execFileSync('git', [...NO_EOL_REWRITE, '-C', UPSTREAM_DIR, 'checkout', '-f', '--detach', 'FETCH_HEAD'], { stdio: 'inherit' });
}

const sha = git(UPSTREAM_DIR, 'rev-parse', 'HEAD');

const blobSha = (buf) => crypto.createHash('sha1').update(`blob ${buf.length}\0`).update(buf).digest('hex');

// One listing of the whole commit: path -> { oid, mode }. `-l` pads the size
// field even though it is unused, and -z keeps paths intact if one ever holds a
// newline. The mode travels with the object because a writeFileSync lands as
// 0644: 23 upstream files are 100755, and Windows cannot even show the drift
// (core.filemode=false), so a mode-blind mirror has to lose them silently.
const entries = new Map();
for (const rec of git(UPSTREAM_DIR, 'ls-tree', '-r', '-l', '-z', 'HEAD').split('\0')) {
  const m = rec.match(/^(\d+) blob ([0-9a-f]+) +\d+\t([\s\S]+)$/);
  if (m) entries.set(m[3], { oid: m[2], mode: m[1] });
}

/** Group the commit's files as tree -> plugin -> [{ rel, oid, mode }]. */
function indexByPlugin() {
  const byTree = new Map(cfg.trees.map((t) => [t, new Map()]));
  for (const [p, { oid, mode }] of entries) {
    const m = p.match(/^([^/]+)\/([^/]+)\/([\s\S]+)$/);
    if (!m || !byTree.has(m[1])) continue;
    const [, tree, name, rel] = m;
    const plugins = byTree.get(tree);
    if (!plugins.has(name)) plugins.set(name, []);
    plugins.get(name).push({ rel, oid, mode });
  }
  return byTree;
}

/** Read every requested object in one `cat-file --batch` pass (~23 MB here). */
function readBlobs(oids) {
  const unique = [...new Set(oids)];
  const out = execFileSync('git', ['-C', UPSTREAM_DIR, 'cat-file', '--batch'], {
    input: `${unique.join('\n')}\n`,
    maxBuffer: 512 * 1024 * 1024,
  });
  const blobs = new Map();
  let pos = 0;
  while (pos < out.length) {
    const nl = out.indexOf(0x0a, pos);
    if (nl < 0) break;
    const m = out.subarray(pos, nl).toString('latin1').match(/^([0-9a-f]+) blob (\d+)$/);
    if (!m) break;
    const size = Number(m[2]);
    blobs.set(m[1], out.subarray(nl + 1, nl + 1 + size));
    pos = nl + 1 + size + 1;
  }
  return blobs;
}

const byTree = indexByPlugin();
const allFiles = [...byTree.values()].flatMap((plugins) => [...plugins.values()].flat());
const blobs = readBlobs(allFiles.map((f) => f.oid));

const corrupt = [];
const previous = readJson(path.join(DATA_DIR, 'last-sha.json'), null);
const previousCatalog = readJson(path.join(DATA_DIR, 'catalog.json'), { plugins: [] });
const previousVersions = new Map(previousCatalog.plugins.map((p) => [p.name, p.version]));

const sourceNames = [];
const versionBumps = [];
const copied = [];

for (const tree of cfg.trees) {
  const plugins = byTree.get(tree) ?? new Map();
  const pluginDirs = [...plugins.keys()]
    .filter((name) => plugins.get(name).some((f) => f.rel === '.zcode-plugin/plugin.json'))
    .sort();

  const stagedDir = path.join(ROOT, tree);
  const staged = fs.existsSync(stagedDir)
    ? fs.readdirSync(stagedDir, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name)
    : [];
  const added = pluginDirs.filter((n) => !staged.includes(n));
  const removed = staged.filter((n) => !pluginDirs.includes(n));

  for (const name of pluginDirs) {
    const files = plugins.get(name);
    const dst = path.join(stagedDir, name);
    const manifestFile = files.find((f) => f.rel === '.zcode-plugin/plugin.json');
    if (!blobs.has(manifestFile.oid)) throw new Error(`missing blob for ${tree}/${name}/.zcode-plugin/plugin.json`);
    const manifest = JSON.parse(blobs.get(manifestFile.oid).toString('utf8'));

    // Rewrite the directory wholesale: files upstream dropped disappear, and no
    // checkout-era CRLF survivor can hide in the tree.
    fs.rmSync(dst, { recursive: true, force: true });
    let written = 0;
    for (const f of files) {
      if (f.rel === '.zcode-plugin-seed.json' || f.rel.endsWith('/.zcode-plugin-seed.json')) continue;
      const buf = blobs.get(f.oid);
      // Guards the batch parser: a desynced read still produces a file, but its
      // bytes would not hash back to the object id we asked for.
      if (!buf || blobSha(buf) !== f.oid) {
        corrupt.push(`${tree}/${name}/${f.rel}`);
        continue;
      }
      const abs = path.join(dst, f.rel);
      fs.mkdirSync(path.dirname(abs), { recursive: true });
      fs.writeFileSync(abs, buf);
      // Restore the upstream executable bit. No-op on Windows, load-bearing on
      // Linux: git there records 100755 from the file system, so omitting this
      // demotes every upstream script to 100644 on the first CI sync.
      if (f.mode === '100755') fs.chmodSync(abs, 0o755);
      written++;
    }
    if (!written) throw new Error(`wrote nothing for ${tree}/${name}`);

    sourceNames.push({ name, tree, dir: `${tree}/${name}` });
    const before = previousVersions.get(name);
    if (before && before !== manifest.version) versionBumps.push({ name, from: before, to: manifest.version });
    if (added.includes(name)) console.log(`[sync] + ${tree}/${name}@${manifest.version}`);
    copied.push({ name, tree, version: manifest.version });
  }

  for (const name of removed) {
    fs.rmSync(path.join(stagedDir, name), { recursive: true, force: true });
    console.log(`[sync] - ${tree}/${name}`);
  }
}

// Timestamps have to be a function of the upstream commit, not of the clock.
// The workflow skips its commit only when `git add -A` stages nothing, so a
// wall-clock stamp minted an empty "sync" commit every single day and buried
// real upstream changes in noise. Pinning to the commit date makes a rerun on
// the same SHA produce byte-identical data/.
const syncedAt = git(UPSTREAM_DIR, 'log', '-1', '--format=%cI', 'HEAD') || new Date().toISOString();

if (corrupt.length) {
  console.error(`[sync] FATAL ${corrupt.length} object(s) did not hash back to their id:`);
  for (const f of corrupt.slice(0, 10)) console.error(`  x ${f}`);
  console.error('[sync] the upstream object database or the batch read is damaged -- delete .upstream and re-run');
  process.exit(1);
}

writeJson(path.join(DATA_DIR, 'last-sha.json'), { sha, syncedAt });
writeJson(path.join(DATA_DIR, 'sync-report.json'), {
  sha,
  previousSha: previous?.sha ?? null,
  syncedAt,
  pluginCount: sourceNames.length,
  added: copied.filter((p) => !previousVersions.has(p.name)).map((p) => p.name),
  removed: previousCatalog.plugins.map((p) => p.name).filter((n) => !copied.some((p) => p.name === n)),
  versionBumps,
  plugins: copied,
});

console.log(`[sync] ${sourceNames.length} plugins @ ${sha.slice(0, 12)} (${versionBumps.length} version bump(s))`);
